param([string]$ModelSimBin='C:\modeltech64_10.6d\win64')
$ErrorActionPreference='Stop'; $root=Split-Path $PSScriptRoot -Parent; $dir=Join-Path $root 'impl/modelsim_voice_mixer'; New-Item -ItemType Directory -Force $dir|Out-Null; Push-Location $dir
try { if(!(Test-Path work/_info)){& "$ModelSimBin/vlib.exe" work}; $src=@('rtl/mgc3130_voice_mixer.sv','sim/tb_mgc3130_voice_mixer.sv')|%{Join-Path $root $_}; & "$ModelSimBin/vlog.exe" -sv -work work @src *>compile.log; if($LASTEXITCODE){Get-Content compile.log;throw 'compile failed'}; & "$ModelSimBin/vsim.exe" -c -onfinish stop -l mixer.log work.tb_mgc3130_voice_mixer -do 'run 1 ms; quit -code 0 -f' *>console.log; if($LASTEXITCODE -or !(Select-String -Path mixer.log -SimpleMatch 'tb_mgc3130_voice_mixer PASS' -Quiet)){Get-Content mixer.log;throw 'mixer failed'}; 'tb_mgc3130_voice_mixer PASS' } finally {Pop-Location}
